(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ko"] = {"ui":{"skip":"본문으로 건너뛰기","back":"← AI-gile로 돌아가기","lang.button":"언어: {name}","lang.dialog":"언어 선택","lang.search":"언어 검색","lang.none":"맞는 언어가 없어요","lang.notYet":"{name}은(는) 아직 번역되지 않았어요","theme.aria":"테마 전환: 밝은 테마, 어두운 테마, 블랙 테마","theme.toLight":"밝은 테마로 전환","theme.toDark":"어두운 테마로 전환","theme.toBlack":"블랙 테마로 전환 (완전한 검정, OLED 화면에 편해요)","words.underline":"페이지에서 이 단어들에 밑줄 긋기","words.underlineHelp":"점선이 있는 단어에 마우스를 올리거나 탭하면 뜻을 볼 수 있어요.","index.title":"AI-gile: 나만의 AI 개발팀을 보드 하나에","index.description":"AI-gile은 AI 코딩 팀을 위한 칸반 보드예요. 내가 자는 동안 팀이 일하고, 나는 결정하고 테스트하고 승인할 일만 짧게 모아 받아요.","hero.logoAlt":"AI-gile 보드 아이콘","hero.h1.html":"나만의 AI 개발팀을 보드&nbsp;하나에.","hero.alpha":"🐣 비공개 프리 알파","hero.alphaTitle":"아직 이르고 덜 다듬어졌어요. 써 봐 주셔서 고마워요!","hero.lede":"내가 자는 동안 팀이 만들어요. 아침에 일어나면 짧은 묶음 하나가 기다려요. 질문 몇 개, 테스트할 것 몇 개, 보라색 다이아몬드 한두 개. 클릭하고 승인하고, 다시 커피 한 잔으로.","dl.windows":"Windows 앱","dl.browser":"브라우저에서 실행","dl.messenger":"📱 휴대폰용 Messenger","dl.soon":"곧 열려요","dl.notify":"🔔 열리면 알려 주세요","dl.notifySmall":"알파 또는 베타","hero.secondary":"애자일이지만 팀은 스탠드업 커피가 필요 없어요. (그래도 스탠드업은 해요.)","pitch.h2":"원하는 만큼의 단어로 만나는 AI-gile","pitch.lede":"한 단어부터 144단어까지 길이를 골라 보세요. 길이마다 그 크기에 맞춰 따로 쓴 설명이에요. 슬라이더를 끌거나 화살표 키를 쓰면 돼요.","pitch.rangeLabel":"단어 수로 고르는 길이","pitch.dice":"🎲 다른 버전","pitch.words.one":"{n}단어","pitch.words.other":"{n}단어","pitch.letters.one":"{n}글자","pitch.letters.other":"{n}글자","pitch.chars.one":"{n}자","pitch.chars.other":"{n}자","count.line.html.one":"지금 보드에 카드가 {n}장 있어요","count.line.html.other":"지금 보드에 카드가 {n}장 있어요","people.humans.html.one":"👥 사람 {n}명","people.humans.html.other":"👥 사람 {n}명","people.agents.html.one":"🤖 에이전트 {n}명","people.agents.html.other":"🤖 에이전트 {n}명","people.working.html.one":"⚡ 지금 {n}명 작업 중","people.working.html.other":"⚡ 지금 {n}명 작업 중","pre.title":"AI-gile: 뭔가 만들고 있어요","pre.description":"여기서 뭔가 만들어지고 있어요. AI 팀이 부탁한 것을 만들고, 만들면서 가르쳐 주는 보드예요. 지금은 친구들과 함께하는 비공개 프리 알파예요.","pre.h1":"여기서 뭔가 만들어지고 있어요. 🤫","pre.line":"AI 팀이 부탁한 것을 만들고, 만들면서 가르쳐 주는 보드예요. 지금은 친구들과 함께하는 비공개 프리 알파예요.","pre.btn":"🔔 열리면 알려 주세요","pre.peek":"유리 너머: 진짜 보드, 실시간이에요. 카드 하나하나가 색깔 막대예요.","pre.peekFake":"유리 너머: 일하는 보드는 이렇게 생겼어요.","features.aria":"할 수 있는 일","f.pile.h":"나를 위한 하나의 묶음","f.pile.html":"<b>내 차례</b>에는 모든 프로젝트에서 나를 기다리는 것이 다 모여요. 질문, 테스트할 것, 사람만 할 수 있는 일까지. 내 대기열이 다음에 할 일과 걸리는 시간을 알려 줘요.","f.sleep.h":"내가 자는 동안 일하는 팀","f.sleep.p":"프로젝트마다 Lead 한 명과 AI 에이전트 팀이 있어요. 카드에 댓글을 달면 팀이 깨어나 일하고, 피곤한 사람도 따라 할 수 있는 단계와 함께 돌려줘요.","f.tester.h":"AI 테스터가 먼저 확인해요","f.tester.p":"나에게 오기 전에 테스터가 앱 사본에서 단계를 따라 해 보고, 본 것을 스크린샷과 함께 보여 줘요. 통과한 것들을 쭉 훑어보고 클릭 한 번으로 승인하세요.","f.proof.h":"약속이 아니라 증거","f.proof.p":"넘겨받을 때마다 바뀐 내용을 보여 줘요. 파일, 변경점, 스크린샷까지. 끝났는지 보려고 앱을 하나하나 열 필요가 없어요.","f.chat.h":"Lead와 대화하기","f.chat.p":"디스코드 같은 사이드바에 프로젝트마다 아이콘이 하나씩 있고, 내가 필요한 곳에는 보라색 다이아몬드가 떠요. Lead에게 아이디어를 보내면 카드와 계획으로 만들어 주고, ✅ 시작 버튼이 함께 나와요.","f.tidy.h":"알아서 정리해요","f.tidy.p":"비슷한 카드는 하나로 합쳐지고, 헷갈리는 제목은 고쳐지고, 토큰 점검으로 코드를 가볍게 유지해요. 오갈 곳이 줄고 신경 쓸 일도 줄어요.","f.private.h":"내 컴퓨터 속, 내 것","f.private.li1":"보드는 내 컴퓨터에서 실행되고 나에게만 응답해요.","f.private.li2":"사람 사이의 비공개 DM은 종단 간 암호화돼요.","f.private.li3":"계정도, 추적기도, 쿠키도 없어요.","f.lang.h":"내 언어로","f.lang.p":"네덜란드어, 웨일스어, 일본어부터 해적, 요다, 클링온까지 120개가 넘는 언어를 지원하고, 전문 용어는 영어로 빠르게 바꿔 볼 수 있어요.","f.service.h":"아이디어에서 진짜 서비스로","f.service.p":"AI로 만든 걸 이제 사람들이 쓰고 있나요? 서비스로 표시하면 보드가 잘 운영하도록 도와줘요. 가동 점검, 공개 상태 페이지, 정리 글이 남는 인시던트, Go가 필요한 변경, 매일 확인하는 백업까지요. 도움말이 하나하나 그때그때 알려 줘요.","msgr.h2":"AI-gile Messenger: 내 팀을 주머니 속에","msgr.p1":"보드를 열지 않아도 AI 팀과 이야기할 수 있어요. 프로젝트 Lead, 친구들과 채팅하고, 카드의 테스트 단계를 보고 바로 답할 수 있어요. 모두 휴대폰에서요.","msgr.p2":"연결하려면 보드에 있는 QR 코드를 스캔하세요. 처음이세요? 친절한 데모 채팅이 하나하나 안내해 드려요.","msgr.when":"Android가 먼저, 그다음 휴대폰과 iPhone용 웹 버전이 나와요.","msgr.who":"내 프로젝트 Lead","msgr.b1":"다크 모드 수정이 끝났어요. 테스트 단계 보내 드릴까요?","msgr.b2":"네, 부탁해요!","msgr.b3":"1. 설정을 여세요. 2. 다크를 고르세요. 제대로 보이나요?","tl.aria":"첫 대화부터 로드맵까지의 타임라인","tl.h2":"첫 대화부터 앞으로의 계획까지","tl.lede":"실제 날짜와 시간이에요. 내 시간대로 보여 줘요. 오늘 이후는 계획일 뿐, 날짜를 약속하지 않아요.","tl.today":"오늘","tl.planned":"계획","tl.doing":"진행 중","tl.cards.one":"카드 {n}장","tl.cards.other":"카드 {n}장","join.h2":"함께해요","join.lede":"AI-gile은 AuDHD가 있고 정신 건강과 몇 번 씨름해 온 수염 난 괴짜 한 명과 참을성 많은 에이전트 여러 명이 만들고 있어요. 지금은 친구들과 함께하는 비공개 알파예요. 문이 열리면 써 보고 싶나요?","join.btn":"관심 등록","join.small":"이메일로만 연락드려요, 그 외엔 없어요","footer.tag":"AI-gile. 추적기도, 쿠키도, 스탠드업 커피도 없어요.","footer.licence":"비즈니스 라이선스","footer.status":"상태","footer.privacy":"저희가 보관하는 것","footer.thanks":"통화는 ChilledChat 덕분이에요","form.sending":"보내는 중…","form.failed":"잘 안 됐어요. 나중에 다시 시도해 주세요.","form.offline":"AI-gile에 연결하지 못했어요. 나중에 다시 시도해 주세요.","form.keep":"답장할 때만 쓰고, 그다음엔 삭제해요. 추적기도, 쿠키도 없어요.","form.keepLink":"저희가 보관하는 것","interest.title":"AI-gile: 알파가 열리면 알려 주세요","interest.description":"이메일을 남기면 AI-gile 비공개 알파나 베타가 열릴 때 알려 드려요.","interest.h1":"🔔 열리면 알려 주세요","interest.lede":"AI-gile은 비공개 프리 알파예요. 이메일을 남기면 자리가 생겼을 때 딱 한 번 연락드려요.","interest.email":"내 이메일","interest.which":"어떤 테스트인가요?","interest.alpha":"비공개 알파: 이르고 거칠고 바뀌는 게 많아요","interest.beta":"베타: 더 안정적이고 더 나중이에요","interest.both":"먼저 열리는 쪽 아무거나","interest.submit":"목록에 넣어 주세요","interest.thanks":"고마워요! 목록에 올랐어요.","licence.title":"AI-gile: 비즈니스 라이선스","licence.description":"회사에서 AI-gile을 쓰나요? 무료 비즈니스 라이선스를 신청해 보세요.","licence.h1":"📜 비즈니스 라이선스","licence.lede":"직장에서 AI-gile을 쓰나요? 누구이고 무슨 일을 하는지 알려 주세요. 세상에 도움이 된다면 라이선스는 무료예요.","licence.company":"회사","licence.website":"웹사이트","licence.what":"하는 일","licence.how":"세상에 어떻게 도움이 되나요","licence.email":"이메일","licence.submit":"신청","licence.thanks":"고마워요! 이메일로 답장드릴게요.","status.title":"AI-gile 상태","status.h1":"AI-gile 상태","status.quiet":"모두 조용해요","status.intro":"AI-gile이 지금 잘 돌아가고 있을까요? 이 페이지는 웹사이트, 보드 공유, 통화, 다운로드를 5분마다 확인해요.","status.up":"정상 작동 중 ({ms}ms 만에 응답)","status.slow":"마지막 확인에 응답이 없어 다시 시도하는 중","status.down":"중단됨: 최근 두 번의 확인에 응답 없음","status.svc.web":"웹사이트","status.svc.web.offers":"이 사이트: AI-gile 소개와 관심 신청 양식","status.svc.boards":"보드 공유","status.svc.boards.offers":"공개 보드, 친구끼리 주고받는 메시지, 초대","status.svc.calls":"통화","status.svc.calls.offers":"AI-gile의 음성, 영상, 화면 공유","status.svc.download":"다운로드","status.svc.download.offers":"Windows 설치 프로그램과 초대 링크","status.checking":"확인 중…","status.offline":"지금은 상태 서비스에 연결할 수 없어요 (다시 시도 중)","status.updated":"{ago} 업데이트됨","status.justNow":"방금","status.min":"{n}분 전","status.hours":"{n}시간 전","status.days":"{n}일 전","privacy.title":"AI-gile: 저희가 보관하는 것","privacy.h1":"저희가 보관하는 것","privacy.lede":"짧게 말하면: 보내 주신 것만, 그것도 잠깐만 보관해요.","privacy.only":"보내 주신 것만 보관해요: 양식에 입력한 내용, 예를 들면 이메일 주소요. 그 밖의 정보는 전혀 없어요.","privacy.sealed":"서버가 읽을 수 없도록 봉인해요. 보내기 전에 내 브라우저 안에서요(오래된 브라우저라면 도착하는 순간에요). 열 수 있는 건 저희 보드뿐이에요.","privacy.server":"저희 보드에 도착하면 바로 서버에서 삭제해요. 30일이 지나도 남아 있는 건 어쨌든 삭제돼요.","privacy.board":"답장을 드릴 때까지만 저희 보드에 보관하고, 그다음엔 거기서도 삭제해요.","privacy.none":"추적기도, 쿠키도, 분석 도구도 없어요.","privacy.local":"언어와 라이트/다크 설정은 내 브라우저에만 남아요. 저희에게 전송되는 일은 절대 없어요.","privacy.ask":"더 빨리 지워 드릴까요? 저희 이메일에 답장해서 알려 주세요.","live.h2":"만들어지는 모습을 실시간으로 보세요","live.caption":"모든 카드는 가려져 있어요. 일의 모양만 보이고, 글은 보이지 않아요.","live.watching.one":"실시간: {n}명 보는 중","live.watching.other":"실시간: {n}명 보는 중","live.last.now":"마지막 카드가 방금 이동했습니다","live.last.min.one":"마지막 카드가 {n}분 전에 이동했습니다","live.last.min.other":"마지막 카드가 {n}분 전에 이동했습니다","live.last.hour.one":"마지막 카드가 {n}시간 전에 이동했습니다","live.last.hour.other":"마지막 카드가 {n}시간 전에 이동했습니다","live.last.day.one":"마지막 카드가 {n}일 전에 이동했습니다","live.last.day.other":"마지막 카드가 {n}일 전에 이동했습니다","live.offline":"실시간 보드가 잠시 쉬고 있어요. 곧 다시 들러 주세요.","live.cols":"백로그|할 일|진행 중|팀 확인 중|직접 테스트할 차례|팀 차례|완료"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["칸반.","로봇들.","맡겼어요."]},{"n":2,"texts":["로봇 칸반.","정리된 에이전트.","아이디어, 완성."]},{"n":3,"texts":["로봇을 위한 칸반.","아이디어가 기능으로.","무료 에이전트 칸반."]},{"n":5,"texts":["에이전트가 움직이는 칸반 보드.","카드는 내가 쓰고 에이전트가 만들어요.","무료에 로컬, 테스트까지, 약간 엉뚱해요."]},{"n":8,"texts":["AI 에이전트가 일하는 무료 칸반 보드예요.","아이디어를 쓰면 에이전트가 만들고 내가 승인해요.","사람 하나와 참을성 많은 로봇 여럿을 위한 애자일."]},{"n":13,"texts":["내 컴퓨터에서 AI 에이전트가 카드를 하나씩 맡아 처리하는 칸반 보드예요.","아이디어를 쓰면 에이전트 팀이 만들고, 테스터가 확인하고, 마지막 결정은 내가 해요.","계정도 추적기도 없는 보드 하나, 로봇 몇 대, 그리고 모든 걸 정하는 나."]},{"n":21,"texts":["AI-gile은 AI 코딩 에이전트와 함께 일하는 칸반 보드예요. 에이전트가 카드를 맡아 만들면 나는 테스트하고 승인하기만 하면 돼요.","프로젝트마다 Lead 한 명과 AI 에이전트로 이루어진 팀이 생겨요. 어느 카드든 댓글을 하나 달면 팀이 바로 일을 시작해요.","내 컴퓨터에서 혼자 돌아가는 무료 개인용 할 일 보드예요. 일하는 건 로봇들이고, 마지막에 좋다고 말하는 사람은 바로 나예요."]},{"n":34,"texts":["보드에 아이디어를 올리면 AI 에이전트 팀이 그것을 실제로 돌아가는 기능으로 만들고, 직접 테스트한 뒤 따라 해 볼 단계와 함께 돌려줘요. 내가 됐다고 말하기 전에는 아무것도 끝난 게 아니에요.","AI-gile은 Rich가 직접 만든 칸반 보드예요. 지금은 이 보드가 관리하는 바로 그 에이전트들의 도움을 아주 많이 받아서 만들었어요. 무료이고 내 컴퓨터에서 돌아가며, 친구들과 함께 쓸 뿐 팔지는 않아요.","백로그부터 완료까지 열이 이어지는 평범한 칸반 보드를 떠올려 보세요. 다만 이 보드에서는 카드를 AI 에이전트가 가져가요. 진행 상황을 알려 주고, 막히면 질문하고, 내가 엄지를 들어 줄 때까지 언제나 기다려요."]},{"n":55,"texts":["AI-gile은 팀원이 전부 AI 에이전트인 칸반 보드예요. 프로젝트마다 일을 계획하는 Lead 한 명과 실제로 만드는 도우미 여러 명이 있어요. 기능이 준비되면 AI 테스터가 직접 써 보고 스크린샷을 찍은 다음, 내 묶음에 올려 줘요. 나는 그대로 승인하거나 댓글을 남겨요. 그러면 팀이 다시 손봐요. 이 모든 과정이 보드 하나 안에서 이뤄져요.","처음에는 한 사람이 여러 AI 코딩 작업을 한꺼번에 챙기려고 만든 작은 도구였는데, 어느새 제대로 된 보드로 자랐어요. 내 컴퓨터에서 돌아가고, 계정이 필요 없고, 추적기도 없어요. 친구와 궁금한 사람에게는 무료예요. 아직 완성된 건 아니라서 거친 부분이나 뜻밖의 일이 있을 수 있어요. 그래도 날마다 조금씩 나아지고 있어요.","솔직한 버전으로 말해 볼게요. 아이디어는 여전히 내가 직접 내야 하고, 결과도 여전히 내가 직접 확인해야 해요. AI-gile이 하는 일은 그 사이의 전부예요. 카드를 순서대로 정리하고, 댓글을 달면 알맞은 에이전트를 깨우고, 무엇이 바뀌었는지 정확히 보여 주고, 이 모든 걸 나를 위한 짧은 묶음 하나로 모아 줘요."]},{"n":89,"texts":["AI-gile은 내 컴퓨터에서 직접 돌리는 무료 칸반 보드예요. 사람이 아니라 프로젝트마다 AI 에이전트 팀이 있어요. 내 아이디어를 카드와 계획으로 바꿔 주는 Lead 한 명, 그리고 우선순위 순서대로 카드를 하나씩 가져가는 도우미들이에요. 무언가 만들어지면 AI 테스터가 시험 단계를 그대로 따라 해 보고, 무엇을 봤는지 나에게 보여 줘요. 그다음에는 내 차례라는 이름의 묶음 하나에서 얌전히 기다려요. 나는 승인하거나 댓글을 남기고, 그러면 팀이 한 번 더 도전해요. 나를 거치지 않고 완료까지 가는 카드는 하나도 없어요.","생각지 못했을 만한 기능도 몇 가지 있어요. 야간 근무는 내가 자는 동안 할 일 열을 계속 채워 두는데, 내 대답이 필요 없는 카드만 골라요. 토큰 카운터는 에이전트가 오늘과 이번 주에 얼마나 썼는지 보여 주고, No Token Mode는 더 이상 쓰지 말라고 알려 줘요. 친구에게 메시지를 보낼 수 있고, 비공개 메시지는 종단 간 암호화돼요. 보드는 네덜란드어, 플랑드르어, 해적어, 클링온어를 포함해 약 120개 언어로 말해요. 하나도 돈이 들지 않고, 누구도 나에게 뭘 팔려고 하지 않아요.","AI-gile은 회사가 아니라 작은 개인 프로젝트예요. Rich는 앱을 하나하나 열어 보지 않고도 여러 AI 코딩 프로젝트를 돌보고 싶었어요. 그래서 에이전트들과 함께 그런 보드를 만들었고, 그다음에는 그 보드를 써서 나머지 부분을 만들었어요. 지금은 비공개 프리 알파라서, 대체로 잘 돌아가는 상태로 친구 몇 명이 쓰고 있어요. 가격 페이지도, 뉴스레터도, 성장 계획도 없어요. 쓸모 있어 보인다면, 조금 더 문이 열릴 때 써 보고 싶다고 말해 주세요. 부담 주는 건 하나도 없고, 그저 조금씩 나아지는 보드 하나가 있을 뿐이에요."]},{"n":144,"texts":["AI-gile은 사람 한 명과 수많은 AI 에이전트를 위한 칸반 보드예요. 내 컴퓨터에서 돌아가고 완전히 무료예요. 프로젝트를 하나 추가하면 프로젝트마다 Lead 한 명과 작은 팀이 생겨요. 디스코드처럼 Lead와 대화하면서 아이디어를 설명하면, Lead가 그것을 카드와 계획으로 바꾸고 내가 시작 버튼을 누를 때까지 기다려요. 팀은 우선순위 순서대로 카드를 처리하는데, 언어 모델을 위해 만든 간단한 명령줄을 써요. 나에게 돌아오기 전에 AI 테스터가 앱 사본에서 단계를 하나씩 따라 해 보고 스크린샷을 붙여요. 끝난 작업은 바뀐 파일과 변경점이 함께 내 묶음에 도착해요. 나는 승인하거나 댓글을 남기고, 그러면 팀이 다시 깨어나 한 번 더 시도해요. 카드를 완료로 옮길 수 있는 사람은 오직 나뿐이에요. 이 모든 일은 내 컴퓨터 안에서만 벌어지고, 계정도 추적기도 쿠키도 없어요. 그래서 아침마다 내가 정할 것만 남아요. 토큰을 얼마나 썼는지도 한눈에 볼 수 있고, 친구끼리 암호화된 메시지를 주고받을 수도 있어요. 아직은 비공개 프리 알파라서 거친 구석이 남아 있지만, 하루하루 좋아지고 있어요.","AI-gile과 함께하는 하루는 대략 이래요. 저녁에 댓글을 몇 개 남겨요. 이 버튼은 자리가 잘못됐다, 저 목록은 정렬되면 좋겠다, 어두운 모드도 있으면 좋겠다 같은 것들이요. 그러고 나서 자러 가요. 에이전트들은 그 댓글을 읽고, 고치고, 테스트하고, 나에게 돌려줘요. 할 일 열이 비면 야간 근무가 백로그에서 내 대답이 필요 없는 카드를 골라 다시 채워 두고요. 아침이 되면 짧은 묶음 하나가 기다려요. 질문 두어 개와 시험해 볼 것 몇 개인데, 졸린 사람도 따라 할 수 있는 단계와 잘 돌아가는 모습이 담긴 스크린샷이 붙어 있어요. 쭉 클릭하면서 좋은 건 승인하고 나머지는 돌려보내요. 토큰 카운터는 이 모든 일에 얼마나 썼는지 보여 주고, 빠듯한 주에는 No Token Mode가 있어요. 그다음에는 아침을 먹어요. 그것만큼은 아직 에이전트가 도와줄 수 없어요. 아침마다 정할 일만 남아 있으니 하루가 한결 가벼워져요.","먼저 AI-gile이 아닌 것부터 말해 볼게요. 스타트업이 아니고, 파는 물건도 아니고, 누구도 내 데이터를 모으지 않아요. 계정도 추적기도 쿠키도 없이 내 컴퓨터에서 돌아가는 무료 보드예요. 그럼 무엇이냐면, 모든 AI 코딩 프로젝트를 한자리에서 한눈에 볼 수 있는 깔끔한 공간이에요. 에이전트 팀이 카드를 처리하고, 결정은 내가 내려요. 비슷한 카드는 하나로 합치고, 헷갈리는 제목은 고치고, 코드가 얼마나 가볍게 유지되는지도 살펴봐요. 네덜란드어와 플랑드르어부터 해적어와 클링온어까지 약 120개 언어로 말해요. 친구끼리 비공개로 암호화된 메시지를 주고받을 수도 있어요. Rich와 참을성 많은 수많은 에이전트가 만들었는데, 대부분은 보드 자신을 써서 만들었어요. 지금은 비공개 프리 알파라서 군데군데 아직 거칠어요. 재미있어 보인다면 정중하게 부탁해 보세요. 일찍 들어올 수도 있어요. 가격표도 구독도 광고도 없고, 서두를 이유도 없어요. 그저 친구들과 천천히 다듬어 가는 보드예요. 마음에 들면 좋고, 아니어도 괜찮아요."]}],"quips":{"1":"한 단어. 대담하죠. 어쩌면 너무 대담한가요.","3":"세 단어. 벌써 웬만한 제품 소개 페이지보다 솔직해요.","8":"여덟 단어. 그래도 스탠드업보다는 짧아요.","21":"참고로 이 길이들은 스토리 포인트예요. 당연하죠.","55":"쉰다섯 단어. 읽는 동안 카드 두 장이 끝났어요.","144":"이게 가장 긴 버전이에요. 233은 없어요. 에이전트들은 자러 갔어요."}},"timeline":{"first-idea.name":"첫 아이디어","first-idea.line":"코드가 생기기도 전, 아주 처음 나눈 대화.","first-board.name":"첫 보드","first-board.line":"자기 자신의 개발을 기록하는 보드: 카드, 열, 드래그 앤 드롭, 프로젝트.","team-roles.name":"팀과 역할","team-roles.line":"에이전트 프로필, 팀 템플릿, 공간, 누가 무엇을 하는지.","install.name":"설치와 릴리스","install.line":"친구도 설치할 수 있는 zip, 자동 업데이트, 채널, 되돌리기.","usage-saver.name":"사용량 절약","usage-saver.line":"실행 비용을 재고, 코드를 가볍게 하고, 한도를 아껴요.","friends.name":"친구와 공유","friends.line":"비공개 DM, 암호화된 릴레이, 초대, 역할, 공유 프로젝트.","languages.name":"언어","languages.line":"모든 화면 문구를 언어 파일로, 네덜란드어와 플랑드르어부터.","ai-tester.name":"AI 테스터","ai-tester.line":"테스터가 모든 인계를 먼저 확인하고 본 것을 보여 줘요.","website.name":"웹사이트","website.line":"aigile.lol, 티저 페이지와 이 타임라인.","streaming.name":"채팅과 스트리밍","streaming.line":"Discord, Twitch, OBS, 스트리머 모드, GIF와 이모지.","no-ai.name":"AI 없는 에디션","no-ai.line":"AI 없이 코딩하는 사람을 위한 보드와 공개 보드.","night-watch.name":"야간 근무","night-watch.line":"야경꾼과 Scrum Master가 내가 자는 동안 팀이 할 일에 집중하게 해요.","p-more.name":"그 밖의 모든 것","p-more.line":"차례를 기다리는 작은 아이디어들.","p-android.name":"휴대폰과 Android","p-android.line":"휴대폰에서 내 보드에 접속하고, 이어서 네이티브 Android 앱까지.","p-release.name":"알파, 그리고 그 너머","p-release.line":"비공개 알파, 라이브 사이트, 그다음 베타.","p-languages.name":"더 많은 언어","p-languages.line":"백 개가 넘는 언어, 그리고 배우는 사람을 위한 몰입 모드.","p-engines.name":"더 많은 AI 엔진","p-engines.line":"에이전트마다 Claude, Codex, Gemini 중에서 고르기.","p-pro.name":"프로의 작업 방식","p-pro.line":"위험 라벨, 머지 게이트, 사고 카드, 가드레일.","p-self.name":"나를 돌보기","p-self.line":"피곤할 때 모드, 자기 돌봄 알림, 4:20.","p-servers.name":"서버와 확장","p-servers.line":"전체 서버 설정, 역할, 성장 계획.","p-livestream.name":"스트리밍 추가 기능","p-livestream.line":"Twitch 채팅, 커스텀 이모지, 공개 라이브 보기."},"words":{"button":"📖 전문 용어","h":"📖 용어 설명","intro":"AI-gile에서 만나는 말을 쉬운 말로 풀어 줘요. 만들기, 안전하게 바꾸기, 쓰는 사람들을 위해 계속 돌아가게 하기, 그리고 AI와 팀으로 일하기까지요.","search":"용어 검색…","none":"맞는 용어가 없어요.","close":"닫기","count":{"one":"단어 {count}개","other":"단어 {count}개"},"groups":[{"id":"build","name":"🛠️ 만들기"},{"id":"change","name":"🔀 안전하게 바꾸기"},{"id":"run","name":"🛎️ 서비스 운영하기"},{"id":"team","name":"🤝 팀으로 일하기 (AI와 함께)"}],"list":[{"id":"repo","g":"build","word":"레포","text":"프로젝트의 코드 폴더와 전체 커밋 기록이에요. 보통 GitHub에도 보관해요.","also":["리포지토리","저장소"]},{"id":"branch","g":"build","word":"브랜치","text":"코드 안의 별도 작업 갈래예요. 메인 버전을 건드리지 않고 변경할 수 있어요.","also":["브랜치들"]},{"id":"commit","g":"build","word":"커밋","text":"코드의 저장된 스냅샷에 바뀐 내용을 짧게 적은 거예요. 언제든 그 시점으로 돌아갈 수 있어요.","also":["커밋들"]},{"id":"push","g":"build","word":"푸시","text":"저장한 스냅샷(커밋)을 이 컴퓨터에서 GitHub로 올려서 백업하고 공유하는 거예요."},{"id":"merge","g":"build","word":"머지","text":"브랜치의 변경 사항을 메인 버전으로 합치는 거예요."},{"id":"pr","g":"build","word":"풀 리퀘스트","text":"브랜치의 변경 사항을 검토하고 메인 버전에 머지해 달라고 요청하는 거예요.","also":["PR","풀 리퀘"]},{"id":"refactor","g":"build","word":"리팩터링","text":"동작은 그대로 두고 코드를 정리하는 거예요. 파일을 작게 나누고, 이름을 분명하게 하고, 반복을 줄여요."},{"id":"bug","g":"build","word":"버그","text":"원래 의도대로 동작하지 않는 것이에요.","also":["버그들"]},{"id":"test","g":"build","word":"테스트","text":"다 된 작업이 요청대로 되는지, 승인하기 전에 직접 써 보며 확인하는 거예요.","also":["테스트들"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"quality assurance(품질 보증)의 줄임말로, 무언가가 배포되기 전에 자동으로 도는 점검이에요. QA가 실패(빨간색)면 무언가 잘못된 거라서, 고칠 때까지 배포할 수 없어요.","also":["품질 점검","품질 보증"]},{"id":"deploy","g":"change","word":"배포","text":"새 버전을 실제로 공개하는 거예요. 예를 들어 사람들이 쓰는 서버에 올려요."},{"id":"release","g":"change","word":"릴리스","text":"함께 배포되는, 이름 붙은 완료 작업 묶음이에요. 무엇이 바뀌었는지 짧은 노트가 붙어요. 🚀 릴리스가 완료된 카드로 노트를 써 줘요.","also":["릴리즈","출시"]},{"id":"rollback","g":"change","word":"롤백","text":"새 버전이 문제를 일으킬 때 마지막으로 잘 돌던 버전으로 돌아가는 거예요. AI-gile에서는 변경마다 적어 둔 되돌리는 단계로 체크리스트를 만들어요.","also":["되돌리기","rollback"]},{"id":"live","g":"change","word":"실서비스","text":"이것저것 시험해 보는 복사본이 아니라, 사람들이 실제로 쓰는 진짜 버전이에요. 개발자들은 운영 환경이나 프로덕션이라고도 해요.","also":["운영 환경","프로덕션","라이브"],"noTip":1},{"id":"change","g":"change","word":"변경","text":"사람들이 의지하는 무언가를 계획해서 바꾸는 거예요. 먼저 적어 둬요: 무엇을, 왜, 위험, 언제, 그리고 되돌리는 방법. 🔀 변경 요청하기로 시작해요.","also":["변경 요청"],"noTip":1},{"id":"risk","g":"change","word":"위험","text":"잘못될 수 있는 일로, 얼마나 일어날 것 같은지와 얼마나 나쁠지로 점수를 매겨요. ⚠️ 위험은 점수가 높은 순으로 한 목록에 모아 두고, 각각 다시 볼 날짜를 붙여요.","also":["리스크","위험 목록"]},{"id":"chgwin","g":"change","word":"변경 가능 시간","text":"변경을 배포해도 되는 시간이에요. 예를 들면 조용한 화요일 저녁이요. 그 시간 밖에서는 긴급한 경우가 아니면 변경 카드를 끝낼 수 없어요.","also":["변경 윈도우","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"변경이 배포되기 직전의 짧은 투표예요. 승인해야 하는 사람이 각자 Go 또는 No go라고 말해요. 모두 동의할 때만 진행돼요.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"승인","text":"일을 시작하기 전에 \"좋아요\"를 기다리는 거예요. 친구가 올린 카드나 변경은 승인하거나 거절할 때까지 ✅ 승인에서 기다려요.","also":["승인 대기"]},{"id":"quiettime","g":"change","word":"조용한 시간","text":"방송, 데모, 밤처럼 아무것도 배포하지 않는 시간이에요. 팀은 계속 일하고 테스트하지만, 배포는 그 시간이 끝날 때까지 기다려요. 다른 곳에서는 변경 동결이라고도 해요.","also":["변경 동결","change freeze"]},{"id":"service","g":"run","word":"서비스","text":"웹사이트나 앱처럼 내가 만들었고 사람들이 의지하는 것으로, 계속 잘 돌아가도록 돌봐요. \"이 프로젝트는 서비스예요\"를 체크하고, 무엇을 제공하는지, 누가 쓰는지, 누가 당직인지 적어요.","also":["서비스들"]},{"id":"uptime","g":"run","word":"가동 점검","text":"몇 분마다 서비스가 아직 응답하는지 자동으로 확인하는 점검이에요. 여러 번 연속으로 실패하면 AI-gile이 알아서 인시던트 카드를 열어요.","also":["가동 시간","업타임","uptime"]},{"id":"statuspage","g":"run","word":"상태 페이지","text":"서비스가 잘 돌아가는지(초록, 주황, 빨강)와 최신 소식을 보여 주는 공개 페이지예요. 쓰는 사람들이 물어보지 않고 직접 확인할 수 있어요.","also":["status page"]},{"id":"desk","g":"run","word":"Service desk","text":"Where questions and reports from the people using your service come in. AI-gile sorts each one into a request, an incident or an idea, and says so when it looks like something already reported.","also":["service desks","help desk","helpdesk"]},{"id":"svcrequest","g":"run","word":"Service request","text":"Someone asking for something ordinary, like a new account or a bit of help, rather than reporting that something is broken. It waits its turn; an incident goes first.","also":["service requests"]},{"id":"incident","g":"run","word":"인시던트","text":"웹사이트가 다운된 것처럼, 지금 쓰고 있는 사람들에게 무언가가 고장 난 상태예요. 🔥 인시던트 카드는 줄을 건너뛰어요. 다시 돌아가게 하는 게 먼저예요.","also":["장애","incident"]},{"id":"major","g":"run","word":"주요 인시던트","text":"큰 인시던트예요. 많은 사람이 영향을 받거나, 돈이나 데이터가 위험해요. 버튼 하나로 모든 팀이 매달리고(스웜), 당직자를 깨우고, 30분마다 상태 업데이트를 요청해요.","also":["주요 장애","대형 장애"]},{"id":"oncall","g":"run","word":"당직","text":"무언가 고장 나면 밤에라도 대응하는 사람이 되는 거예요. 서비스마다 당직 팀원이 한 명 있고, 그 서비스의 인시던트에서는 그 사람을 가장 먼저 깨워요.","also":["온콜","on-call","호출 대기"]},{"id":"replyby","g":"run","word":"답변 기한","text":"카드가 첫 답을 기다릴 수 있는 시간이에요. 예를 들어 인시던트는 1시간이에요. 그 뒤에는 빨간 시계가 붙어서, 아무것도 조용히 잊히지 않아요. 응답 목표라고도 해요.","also":["응답 목표","응답 기한"]},{"id":"postmortem","g":"run","word":"사후 분석","text":"인시던트 뒤에 짧게 돌아보는 거예요. 무슨 일이 있었는지, 무엇이 도움이 됐는지, 무엇을 바꿀지를 아무도 탓하지 않고 정리해요. 이게 없으면 인시던트를 닫을 수 없어요.","also":["포스트모템","post-mortem","사후 검토"]},{"id":"problem","g":"run","word":"문제","text":"하나 이상의 인시던트 뒤에 숨은 원인이에요. 🧩 문제 카드는 자꾸 되풀이되는 인시던트를 묶어서, 원인을 찾아 완전히 고치게 해요.","also":["문제 관리","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"근본 원인","text":"눈에 보인 증상이 아니라, 무언가가 고장 난 진짜 이유예요. 근본 원인을 고치면 그 인시던트는 다시 생기지 않아요.","also":["원인","root cause"]},{"id":"workaround","g":"run","word":"임시 조치","text":"진짜 해결책이 준비될 때까지 계속 돌아가게 하는 방법이에요. 예를 들면 멈췄을 때 다시 시작하는 거요. 문제 카드에 적어 두니까 아무도 다시 알아낼 필요가 없어요.","also":["우회 방법","workaround","임시 방법"]},{"id":"knownerror","g":"run","word":"알려진 오류","text":"원인을 알고 임시 조치도 있지만 아직 고치지 않은 문제예요. 🧩 알려진 오류에 목록이 있어서, 모두가 다시 파고들지 않고 임시 조치를 써요.","also":["known error"]},{"id":"runbook","g":"run","word":"런북","text":"익숙한 종류의 문제를 고치는 단계별 안내예요. 그래서 매번 같은 방법으로 빨리 처리돼요. 큰 인시던트 뒤에 팀이 하나를 제안하면 여러분이 확인해요.","also":["runbook","운영 매뉴얼"]},{"id":"ci","g":"run","word":"Configuration item","text":"One thing your service depends on, like a server, a domain, a certificate, a key or a supplier. 🗂️ Configuration items lists them per service, so you can see what an incident affects and what needs renewing or a backup.","also":["configuration items"]},{"id":"expiry","g":"run","word":"Expiry date","text":"AI-gile keeps an eye on dates like when a certificate or a domain runs out. Within 30 days of the date it makes one card to renew it, so nothing stops working by surprise.","also":["expiry dates","expiry","expiry watch"]},{"id":"backup","g":"run","word":"백업","text":"예전 데이터를 저장해 둔 복사본으로, 무언가가 사라지거나 망가지면 기댈 수 있어요. AI-gile은 매일 보드를 백업해요.","also":["backup","백업본"]},{"id":"restore","g":"run","word":"복원","text":"백업에서 데이터를 되살리는 거예요. 백업은 복원할 수 있다는 걸 알아야 진짜 의미가 있으니, 가끔 해 볼 만해요.","also":["복구","restore"]},{"id":"svcreview","g":"run","word":"Service review","text":"A look back at one month of a service: incidents opened and fixed, how quickly people got an answer, uptime and tokens used. The Monthly review shows it for each service.","also":["service reviews","monthly review","monthly reviews"]},{"id":"accessreview","g":"run","word":"Access review","text":"Checking every 90 days who can still get in: share links, friends’ roles and kept secrets. You keep or remove each one, so old access doesn’t linger.","also":["access reviews"]},{"id":"improvements","g":"run","word":"Improvement list","text":"Everything the team decided to get better at, in one place: retro suggestions, review actions and problem fixes, each with its status. Find it under 📈 Improvements.","also":["improvement lists","improvements"]},{"id":"tokencap","g":"run","word":"Token cap","text":"A monthly limit on the tokens a service’s agents may use. At 80% you get a warning; at 100% their background work waits until next month or until you raise the cap.","also":["token caps"]},{"id":"backlog","g":"team","word":"백로그","text":"아직 계획에 넣지 않은 아이디어와 작업이에요. 할 일로 옮기기 전에는 아무것도 진행되지 않아요."},{"id":"sprint","g":"team","word":"스프린트","text":"정해 둔 카드를 끝내기 위한 짧은 작업 기간이에요 (보통 1~2주).","also":["스프린트들"]},{"id":"standup","g":"team","word":"스탠드업","text":"짧은 점검 모임이에요. 각 팀원이 한 일, 다음에 할 일, 막고 있는 것을 말해요.","also":["스탠드업","스탠드 업"]},{"id":"kanban","g":"team","word":"칸반","text":"열(할 일, 진행 중, 완료)이 있는 보드예요. 작업이 진행되면 카드가 왼쪽에서 오른쪽으로 움직여요."},{"id":"wip","g":"team","word":"WIP 제한","text":"진행 중인 작업(Work in progress)이에요. 한 열이 담을 수 있는 최대 카드 수로, 팀이 새 일을 벌이기 전에 하던 일을 끝내게 해요.","also":["WIP"]},{"id":"dod","g":"team","word":"완료의 정의","text":"카드를 여러분에게 넘기기 전에 \"끝났다\"가 무슨 뜻인지 정한 팀의 짧은 체크리스트예요. 예를 들어 테스트했고 설명했다는 거요. 쌍둥이인 준비의 정의(Definition of Ready)는 카드가 시작할 만큼 분명해진 때를 정해요.","also":["Definition of Done","준비의 정의","Definition of Ready"]},{"id":"testpile","g":"team","word":"테스트 더미","text":"여러분이 해 보길 기다리는 완료된 카드들로, 하나씩 차례로 나와요. 받아들이거나 메모와 함께 돌려보내면 다음 카드가 나와요.","also":["test pile"]},{"id":"retro","g":"team","word":"회고","text":"팀이 어떻게 일하는지 돌아보고, 더 잘할 한 가지를 정하는 거예요. AI-gile에서는 회고가 팀의 일하는 방식을 바꾸자고 제안하고, 여러분이 Go 또는 아직이라고 답해요.","also":["레트로","retro","회고 회의"]},{"id":"peerreview","g":"team","word":"동료 검토","text":"한 쌍의 눈이 더 있는 거예요. 각 카드의 작업이 여러분에게 오기 전에 다른 AI가 확인해서, 실수가 덜 빠져나가요.","also":["코드 리뷰","피어 리뷰","code review"]},{"id":"swarm","g":"team","word":"스웜","text":"총동원이에요. 모든 팀이 다른 일을 내려놓고, 급한 프로젝트 하나가 해결될 때까지 도와요. 그동안 다른 프로젝트는 기다려요.","also":["swarm","스워밍"]},{"id":"scrummaster","g":"team","word":"스크럼 마스터","text":"일이 계속 흘러가게 하는 사람이에요. 막힌 카드를 찾아내고, 팀을 재촉하고, 여러분을 기다리는 게 뭔지 알려 줘요. AI-gile에서는 리드 스크럼 마스터가 모든 프로젝트에서 이 일을 해요.","also":["리드 스크럼 마스터","Scrum Master"]},{"id":"agent","g":"team","word":"에이전트","text":"혼자서 작업을 하는 AI예요. 코드를 읽고, 바꾸고, 점검을 돌리고, 결과를 보고해요.","also":["에이전트들"]},{"id":"token","g":"team","word":"토큰","text":"AI 사용량을 세는 단위예요. 대략 읽거나 쓴 글자 몇 개 정도예요. 토큰이 적을수록 요금제가 더 많이 남아요.","also":["토큰들"]},{"id":"hook","g":"team","word":"훅","text":"정해진 순간에 저절로 실행되는 작은 명령이에요. 예를 들어 AI 세션이 시작될 때 실행되어, 팀이 내 댓글을 받아 보게 해요.","also":["훅들"]}]}};
